import{z as o,x as l,o as t,c as d,q as r,j as s,D as B,d as a,s as A,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"指数衍生品","description":"","frontmatter":{"title":"指数衍生品","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/etf-derivatives.md","filePath":"quant/etf-derivatives.md","lastUpdated":1791413859000}'),F={name:"quant/etf-derivatives.md"};function p(C,E,f,c,h,u){const n=l("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="指数衍生品" tabindex="-1">指数衍生品 <a class="header-anchor" href="#指数衍生品" aria-label="Permalink to &quot;指数衍生品&quot;">​</a></h1><div class="epigraph"><p>同一份指数暴露，期货用保证金记、互换用融资价差记、ETF 用全额本金记；载体的区别不在风险，在成本放哪一栏、约束长什么样子。</p><footer>—— 持有成本定价见 Cornell and French, 1983；Modest and Sundaresan, Journal of Financial Economics, 1983；合约规格据 CME、CBOE 与中金所规则整理</footer></div><p><a href="/quant/etf-smart-beta">上一课</a>把因子写成了产品，但暴露的载体不止现货份额一种。指数期货、总收益互换与 ETF 是同一个标的的三种记账方式。缺口是选型：持有期多长、资金占多少、空头与杠杆怎么做、对手方风险谁担。基差的定价基础——持有成本与期现套利——已在<a href="/quant/spot-forward-df">即期、远期与折现</a>立起；A 股期货贴水的对冲成本核算见<a href="/quant/cn-index-basis-hedge-cost">股指期货基差与对冲成本</a>与<a href="/quant/cn-index-fut-basis">股指期货保证金与贴水</a>。本课写三张载体的对照表与转换机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三种载体各付一种成本。期货：占少量保证金，但要管展期，贴水是对冲者每年确定要付的租金，且有空头便利与杠杆。互换：按「指数收益减融资价差」交换，无展期，但要管对手方与 ISDA 文档、支付抵押品保证金。ETF：全额本金、无对手方（基金结构隔离），但付费率、承担跟踪误差，进出有点差与折溢价。同一个指数，三条路径的总成本可以差出几十个基点，且随利率环境与贴水结构移动。只比费率选载体，等于把展期租金和抵押品占用当成免费。</p><p><span class="marginnote">术语翻译：「贴水」就是期货价格比指数现货便宜的那一块，年化看是多头每年固定付出的租金——做空指数的人（对冲与替代需求）愿意折价卖，多头买便宜合约、到期按更高的现货价交割，差价就是成本。</span></p><p><span class="marginnote">指数期权与 ETF 期权的差别常被当成细节：股指期权现金交割、按开盘价（或专门结算价）定损益，仓位大时不需要在到期日卖出一篮子股票；ETF 期权实物交割、行权即交股票，流动性与保证金结构也不同。对冲同一名义暴露，两张合约的展期日历与隐含波动率曲面并不重合，见<a href="/quant/cn-etf-options">ETF 期权市场</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型写成四问。持有多长：期货按展期次数计成本，越长越要跟贴水结构谈判；互换适合一年以上、议价能力强的机构。资金与杠杆：期货的保证金效率换来现金流管理义务；ETF 全额占用但免盯市。空头来向：做空指数暴露，期货与互换天然，ETF 要融券或反向产品。对手方与文档：互换把信用风险换成融资价差，清算中央化程度决定保证金模型。四问答完，载体基本自选；剩下的差异是税、会计与偿付能力资本的处理。</p><p><span class="marginnote">数字实例：同样持有 1000 万指数暴露一年——ETF 全额占用 1000 万、付 15bp 费率；期货只占约 12% 保证金即 120 万，但若年化贴水 40bp，租金 4 万；互换按融资价差 20bp 记账。三条路径总成本能差几十个基点，且随利率与贴水移动。</span></p>',10)),(t(),s(i,null,{default:B(()=>[A(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E9%9C%80%E8%A6%81%E7%9A%84%E6%8C%87%E6%95%B0%E6%9A%B4%E9%9C%B2%22%5D%20--%3E%20F%5B%22%E6%9C%9F%E8%B4%A7%EF%BC%9A%E4%BF%9D%E8%AF%81%E9%87%91%20%2B%20%E5%B1%95%E6%9C%9F%E7%A7%9F%E9%87%91%22%5D%0A%20%20EXP%20--%3E%20S%5B%22%E4%BA%92%E6%8D%A2%EF%BC%9A%E8%9E%8D%E8%B5%84%E4%BB%B7%E5%B7%AE%20%2B%20%E5%AF%B9%E6%89%8B%E6%96%B9%22%5D%0A%20%20EXP%20--%3E%20E%5B%22ETF%EF%BC%9A%E5%85%A8%E9%A2%9D%E6%9C%AC%E9%87%91%20%2B%20%E8%B4%B9%E7%8E%87%E4%B8%8E%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20F%20--%3E%20B1%7B%22%E8%B4%B4%E6%B0%B4%E5%8F%AF%E6%8E%A5%E5%8F%97%E3%80%81%E8%83%BD%E7%AE%A1%E5%B1%95%E6%9C%9F%3F%22%7D%0A%20%20S%20--%3E%20B2%7B%22%E6%9C%89%20ISDA%20%E4%B8%8E%E6%8A%B5%E6%8A%BC%E5%93%81%E7%BA%BF%3F%22%7D%0A%20%20E%20--%3E%20B3%7B%22TD%20%E9%AA%8C%E6%94%B6%E9%80%9A%E8%BF%87%E3%80%81%E7%82%B9%E5%B7%AE%E5%8F%AF%E6%89%BF%E5%8F%97%3F%22%7D%0A%20%20B1%20--%3E%20SW%5B%22%E8%BD%BD%E4%BD%93%E8%BD%AC%E6%8D%A2%EF%BC%9A%E4%B8%89%E8%80%85%E9%97%B4%E8%BF%81%E7%A7%BB%22%5D%0A%20%20B2%20--%3E%20SW%0A%20%20B3%20--%3E%20SW%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("三条价格被一条套利链钉住：期货偏离持有成本、ETF 偏离可复制篮子、互换价差偏离融资成本，任一缺口过大都会召唤资本搬平——机制与"),e("a",{href:"/quant/etf-create-redeem-arb"},"第二课"),a("的申赎套利同构，只是腿换成了期货与抵押品。贴水不是偏差而是价格：空头需求（对冲与替代）压低期货价格，滚动展期的损失就是多头付给空头的租金，"),e("a",{href:"/quant/cn-index-basis-hedge-cost"},"股指期货基差与对冲成本"),a("把它算成了年化数字。载体转换因此是机构的标准动作：贴水深时把期货暴露迁回现货 ETF，贴水浅时反向；迁移成本（点差、税、结算时滞）决定阈值，不决定方向。")],-1)),(t(),s(i,null,{default:B(()=>[A(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%9C%9F%E8%B4%A7%E8%B4%B4%E6%B0%B4%E7%8A%B6%E6%80%81%E5%8F%98%E5%8C%96%22%5D%20--%3E%20Q%7B%22%E8%B4%B4%E6%B0%B4%E6%B7%B1%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E6%B7%B1%22%7C%20M1%5B%22%E6%8A%8A%E6%9C%9F%E8%B4%A7%E6%9A%B4%E9%9C%B2%E8%BF%81%E5%9B%9E%E7%8E%B0%E8%B4%A7%20ETF%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B5%85%22%7C%20M2%5B%22%E8%BF%81%E5%9B%9E%E6%9C%9F%E8%B4%A7%2C%20%E4%BA%AB%E4%BF%9D%E8%AF%81%E9%87%91%E6%95%88%E7%8E%87%22%5D%0A%20%20M1%20--%3E%20C%5B%22%E7%AE%97%E8%BF%81%E7%A7%BB%E6%88%90%E6%9C%AC%3A%20%E7%82%B9%E5%B7%AE%2B%E7%A8%8E%2B%E7%BB%93%E7%AE%97%E6%97%B6%E6%BB%9E%22%5D%0A%20%20M2%20--%3E%20C%0A%20%20C%20--%3E%20T%7B%22%E6%88%90%E6%9C%AC%E8%B6%85%E8%BF%87%E5%B9%B4%E5%8C%96%E7%A7%9F%E9%87%91%E5%B7%AE%E5%90%97%22%7D%0A%20%20T%20--%3E%7C%22%E6%98%AF%22%7C%20K%5B%22%E7%95%99%E5%9C%A8%E5%8E%9F%E8%BD%BD%E4%BD%93%22%5D%0A%20%20T%20--%3E%7C%22%E5%90%A6%22%7C%20GO%5B%22%E6%89%A7%E8%A1%8C%E8%BF%81%E7%A7%BB%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>展期执行的专门技术——移仓节奏、价差单、到期日历——属于期货课程的执行专题，本课只把贴水记为成本项。期权的波动率面与波动率衍生品（VIX、方差互换）是波动率课程的对象；本课只指出指数期权与 ETF 期权的合约差异会影响对冲的展期日历，见<a href="/quant/cn-etf-options">ETF 期权市场</a>。也不把三载体写成可完全替代：清算资质、跨境限制与合规口径会把某一条路径直接关掉，选型表的第一列永远是「可行」，第二列才是「便宜」。</p><p><span class="marginnote">常见误区：只比管理费选载体。ETF 表面 15bp 费率可能比期货 40bp 贴水便宜，但全额占用 1000 万现金的机会成本与再投资约束没算进去；反过来，期货的保证金效率在急跌追保时可能变成强平风险。先问可行，再算全成本。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>期货、互换、ETF 是同一暴露的三种记账：保证金加展期租金、融资价差加对手方、全额本金加费率与误差。</li><li>贴水是对冲的年化租金，不是市场失效；选载体先问可行再问便宜。</li><li>三条价格被套利链钉住，载体转换的阈值由迁移成本决定。</li><li>指数期权现金交割、ETF 期权实物交割，展期日历与波动率面不重合。</li><li>出处：Cornell and French（1983）；Modest and Sundaresan, <em>Journal of Financial Economics</em>, 1983；合约规格据 CME、CBOE 与中金所规则；A 股贴水核算见<a href="/quant/cn-index-basis-hedge-cost">股指期货基差与对冲成本</a>。</li></ul>',5))])}const m=o(F,[["render",p]]);export{T as __pageData,m as default};
